static void pb_tick_price(void* user, int64_t req_id, int64_t field, double price, uint32_t attrib) noexcept {
  ibx::Sink* s = static_cast<ibx::Sink*>(user);
  try {
    const auto a3 = ibx::tick_attrib(attrib);
    if (s->quiet(ibx::PB_tickPrice) || ibx::pb::tickPrice(*s, (int)req_id, (TickType)field, price, a3)) s->w->tickPrice((int)req_id, (TickType)field, price, a3);
  } catch (...) { s->failed(); }
}

