static void pb_tick_option_computation(void* user, int64_t req_id, int64_t tick_type, int64_t tick_attrib, double implied_vol, double delta, double opt_price, double pv_dividend, double gamma, double vega, double theta, double und_price) noexcept {
  ibx::Sink* s = static_cast<ibx::Sink*>(user);
  try {
    if (!s->quiet(ibx::PB_tickOptionComputation)) {
      s->flush();
      if (s->wants(ibx::PB_tickOptionComputation)) {
        protobuf::TickOptionComputation m;
        ibx::pb::head_tickOptionComputation(m, (int)req_id, (TickType)tick_type, (int)tick_attrib, implied_vol, delta, opt_price, pv_dividend, gamma, vega, theta, und_price);
        ++ibx::protoMessagesBuilt;
        s->w->tickOptionComputationProtoBuf(m);
        s->given();
      }
    }
    s->w->tickOptionComputation((int)req_id, (TickType)tick_type, (int)tick_attrib, implied_vol, delta, opt_price, pv_dividend, gamma, vega, theta, und_price);
  } catch (...) { s->failed(); }
}

